/// <summary>
/// PricingAttribute of table <c>CustTable</c> field SalesGroup.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, SalesGroup))]
internal class GUPPricingAttributeCustTableSalesGroup extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, SalesGroup);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    Custtable               custTable;
    CommissionSalesGroup    commissionSalesGroup;

    while select SalesGroup from custtable
        group by SalesGroup
        join commissionSalesGroup
        group by GroupId, Name
        where custTable.SalesGroup == commissionSalesGroup.GroupId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(commissionSalesGroup.GroupId, commissionSalesGroup.Name);
        ret.add(valueObject);
    }
    return ret;
}
